package com.nextfeet.nextfeet.model; import java.math.BigDecimal; public class Zapatilla { private Integer id; private String sku,nombre,marca,descripcion,materiales,colores,imagen,estado,talla; private BigDecimal precio; private Integer categoriaId,cantidad; public Zapatilla(){} public Zapatilla(Integer id,String sku,String nombre,String marca,BigDecimal precio,String descripcion,String materiales,String colores,String imagen,Integer categoriaId,String estado){this.id=id;this.sku=sku;this.nombre=nombre;this.marca=marca;this.precio=precio;this.descripcion=descripcion;this.materiales=materiales;this.colores=colores;this.imagen=imagen;this.categoriaId=categoriaId;this.estado=estado;} public Integer getId(){return id;} public void setId(Integer v){id=v;} public String getSku(){return sku;} public void setSku(String v){sku=v;} public String getNombre(){return nombre;} public void setNombre(String v){nombre=v;} public String getMarca(){return marca;} public void setMarca(String v){marca=v;} public BigDecimal getPrecio(){return precio;} public void setPrecio(BigDecimal v){precio=v;} public String getDescripcion(){return descripcion;} public void setDescripcion(String v){descripcion=v;} public String getMateriales(){return materiales;} public void setMateriales(String v){materiales=v;} public String getColores(){return colores;} public void setColores(String v){colores=v;} public String getImagen(){return imagen;} public void setImagen(String v){imagen=v;} public Integer getCategoriaId(){return categoriaId;} public void setCategoriaId(Integer v){categoriaId=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} public String getTalla(){return talla;} public void setTalla(String v){talla=v;} public Integer getCantidad(){return cantidad;} public void setCantidad(Integer v){cantidad=v;} }